class Carro {
    constructor(marca : number, modelo : number, valor : number) {
        this.marca = marca
        this.valor = valor
        this.modelo = "modelo"
    }
}

function mesmaMarca(c1, c2) {
    return c1.modelo == c2.modelo
}

class Xyz {
    a : number = 0
    b : number = 0
    c : number = 0
}

function d(x : Xyz[]) : void {
    for (let i : number = 0; i < x.length; i++) {
        x[i].a = x[(i+1) % x.length].b
        x[i].b = x[(i+1) % x.length].c
        x[i].c = x[(i+1) % x.length].a

        console.log(x[i].a, x[i].b, x[i].c)
    }
}

let array : Xyz[] = [ {a:1, b:2, c:3}, {a:4, b:5, c:6} ]

d(array)
